function resourceKindContract({
  className,
  identifierType,
  identifierArity,
  acquisitions,
  cleanupAdapterId,
  absenceAdapterId,
  phase,
  policy,
  deleteAuthority = false,
  restoreAuthority = false,
  operationSlots = "PCA",
}) {
  return deepFreezeExact({
    class: className,
    identifierType,
    identifierArity,
    acquisitions,
    cleanupAdapterId,
    absenceAdapterId,
    cleanupPhase: { success: phase.success, failure: phase.failure },
    cleanupPolicy: policy,
    deleteAuthority,
    restoreAuthority,
    operationSlots,
  });
}

